import java.util.Scanner;

public class IceRink {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int K = sc.nextInt();
        int[] A = new int[K];
        for (int i = 0; i < K; i++) {
            A[i] = sc.nextInt();
        }

        long low = 2, high = 2;
        for (int i = K - 1; i >= 0; i--) {
            long a = A[i];
            // Before round i+1: children = X, after = Y
            // Then X = Y * a + r where 0 <= r < a
            // So newLow = low * a
            // newHigh = high * a + (a - 1)
            low = low * a;
            high = high * a + (a - 1);
            if (low > high) {
                System.out.println(-1);
                return;
            }
        }

        System.out.println(low + " " + high);
    }
}

