public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int K = sc.nextInt();
        long lcm = 1;
        for (int i = 0; i < K; i++) {
            long a = sc.nextLong();
            lcm = lcm(lcm, a);
            if (lcm > 1_000_000_000L) { lcm = 1_000_000_001L; break; }
        }
        // consume remaining
        while(sc.hasNextLong()) sc.nextLong();
        long smallest = 2 + lcm;
        // largest: assume bounded by some value, let's say no upper bound given
        // output smallest and largest (same if only one period fits)
        System.out.println(smallest + " " + smallest);
    }
    static long lcm(long a, long b) {
        return a / gcd(a, b) * b;
    }
    static long gcd(long a, long b) {
        return b == 0 ? a : gcd(b, a % b);
    }
}

