        // floor(x/a)*a = m, m in [lo,hi], a|m, x in [m, m+a-1]
        // new lo: smallest m >= lo with a|m -> ceil(lo/a)*a
        // new hi: largest m <= hi with a|m -> floor(hi/a)*a, then x up to m+a-1
        long long new_lo_m = ((lo + a - 1) / a) * a;
        long long new_hi_m = (hi / a) * a;
        if (new_lo_m > new_hi_m) { lo = 1; hi = 0; break; } // empty
        lo = new_lo_m;
        hi = new_hi_m + a - 1;
    }

    if (lo > hi) printf("-1\n");
    else printf("%lld %lld\n", lo, hi);
    return 0;
}

