typedef long long ll;

int main(void) {
    int K;
    if (scanf("%d", &K) != 1) return 0;

    ll *A = (ll *)malloc(sizeof(ll) * K);
    for (int i = 0; i < K; i++) scanf("%lld", &A[i]);

    ll low = 2, high = 2;

    for (int i = K - 1; i >= 0; i--) {
        ll a = A[i];

        ll newLow = ((low + a - 1) / a) * a;
        ll newHigh = (high / a) * a + (a - 1);

        if (newLow > newHigh) {
            printf("-1\n");
            free(A);
            return 0;
        }

        low = newLow;
        high = newHigh;
    }

    printf("%lld %lld\n", low, high);
    free(A);
    return 0;
}
